import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-01-23 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-01-23 -- Ceph Performance Meeting","date":"2020-01-23T00:00:00.000Z","updated":"2020-01-30T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","分区自动缩放","空间放大","OSD","Rados","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-23_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-01-23_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2020/2020-01-23_-_-_Ceph_Performance_Meeting.md"};function l(i,e,s,_,g,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>PG自动缩放</strong>: 会议讨论了PG自动缩放的提案，其中包括将PG数量默认设置为32的提案。</li><li><strong>PR更新</strong>: Radek的PR改变了标准列表T的编码方式，不再使用无缓冲复制。Keefe的PR涉及透明比较器，以避免额外工作。Igor的PR通过改变数据结构减少了缓存PG的内存占用。</li><li><strong>性能优化</strong>: 讨论了OSD PG日志条目的点改变PR，以及关于分裂读IO的PR，这些可能有助于性能提升。</li><li><strong>RGW过滤逻辑</strong>: Erica添加的RGW过滤逻辑已通过QA测试，但需要调整。</li><li><strong>空间放大问题</strong>: Igor讨论了blob空间放大问题，特别是使用记录池时可能出现的问题。建议将最小分配大小设置为4k，但仍在考虑调整。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>分配器行为</strong>: 讨论了分配器在处理大IO请求时的行为，特别是是否应该返回连续的块或小的碎片。</li><li><strong>最小分配大小</strong>: 讨论了在不同设备和使用场景下，最小分配大小的最佳设置。</li><li><strong>性能与空间利用的权衡</strong>: 讨论了在性能和空间利用之间的权衡。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>分配器调整</strong>: 决定进一步调查分配器的行为，特别是是否能够优化以返回更大的连续块。</li><li><strong>最小分配大小设置</strong>: 对于Octopus版本，决定对于HDD，如果不能及时解决分配器问题，将回退到64k的最小分配大小。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>分配器测试</strong>: Igor将尝试调整分配器，看是否能改善大IO请求的处理。</li><li><strong>性能测试</strong>: 重新运行性能测试，特别是关注大IO请求的性能变化。</li><li><strong>RGW逻辑调整</strong>: 重新调整RGW过滤逻辑，并考虑是否需要重新进行测试。</li><li><strong>空间放大问题研究</strong>: 继续研究blob空间放大问题，并考虑是否需要调整最小分配大小设置。</li></ul><p>会议重点讨论了Ceph的PG自动缩放、性能优化和空间放大问题，并制定了相应的后续行动计划。</p>',10)])])}const p=t(n,[["render",l]]);export{c as __pageData,p as default};
